def play(bridge):
    def _run():
        for bones in FRAMES:
            if not bones or len(bones) == 0:
                continue
            try:
                bridge.push_sync_pose(bones)
            except Exception as e:
                print(f"[AutoAnim] Error pushing frame: {e}")
            time.sleep(1.0 / FPS)
            
    t = threading.Thread(target=_run, daemon=True, name="AutoAnim_AutoAnim_8b31c572")
    t.start()
